import json, time, sys, os
from obswebsocket import obsws, requests
cfg='/home/avinas/.config/obs-studio/plugin_config/obs-websocket/config.json'
with open(cfg) as f:
    conf=json.load(f)
port=conf.get('server_port',4455)
password=conf.get('server_password','')
print('using port',port,'password set?', bool(password))
try:
    c=obsws('localhost', port, password)
    c.connect()
    print('connected, server version:', c.call(requests.GetVersion()).getObsWebSocketVersion())
    try:
        kinds_resp=c.call(requests.GetInputKindList())
        kinds = kinds_resp.getInputKinds() if hasattr(kinds_resp,'getInputKinds') else kinds_resp.datain
        print('input kinds count', len(kinds))
        # show some kind ids
        for k in kinds[:20]:
            print(' -', k.get('id') if isinstance(k, dict) else getattr(k,'getId', lambda:repr(k))())
    except Exception as e:
        print('GetInputKindList failed', e)
    try:
        inputs_resp=c.call(requests.GetInputList())
        inputs = inputs_resp.getInputs() if hasattr(inputs_resp,'getInputs') else inputs_resp.datain
        print('\ninputs:')
        for i in inputs:
            print(i)
    except Exception as e:
        print('GetInputList failed', e)
    try:
        sl=c.call(requests.GetSceneList())
        print('\nscenes:')
        for s in sl.getScenes():
            print(' -', s)
    except Exception as e:
        print('GetSceneList failed', e)
    try:
        # current program scene
        cs=c.call(requests.GetCurrentProgramScene())
        scene_name = cs.getCurrentProgramSceneName() if hasattr(cs,'getCurrentProgramSceneName') else None
    except Exception:
        try:
            cs2=c.call(requests.GetCurrentScene())
            scene_name = cs2.getName() if hasattr(cs2,'getName') else None
        except Exception:
            scene_name=None
    print('\ncurrent scene:', scene_name)
    if scene_name:
        try:
            items = c.call(requests.GetSceneItemList(sceneName=scene_name)).getSceneItems()
            print('scene items:')
            for it in items:
                print(it)
        except Exception as e:
            print('GetSceneItemList failed', e)
    # check for video-like input
    video_input=None
    for i in inputs:
        kind = i.get('inputKind') or i.get('inputKindId') or i.get('type') or i.get('inputKindId') if isinstance(i, dict) else None
        name = i.get('inputName') or i.get('input') or i.get('name') if isinstance(i, dict) else None
        ks = (kind or '').lower() if kind else ''
        if any(x in ks for x in ('monitor','display','pipewire','screen','window')):
            video_input = name
            break
    print('\nfound video input:', video_input)
    if not video_input:
        print('Attempting to create a monitor input (best-effort)')
        # Try several likely kind ids
        candidates = ['monitor_capture','pipewire-source','pipewire-monitor','pipewire-screen-capture','screen_capture','xcomposite_input']
        created=None
        for cand in candidates:
            try:
                print(' try create', cand)
                c.call(requests.CreateInput(inputName='AutoScreen', inputKind=cand, inputSettings={}))
                created='AutoScreen'
                print(' created', cand)
                break
            except Exception as e:
                print('  failed', cand, e)
        if created:
            time.sleep(0.5)
            try:
                inputs2=c.call(requests.GetInputList()).getInputs()
                print('inputs after create:', inputs2)
            except Exception as e:
                print('GetInputList after create failed', e)
            # add scene item
            if scene_name:
                try:
                    c.call(requests.AddSceneItem(sceneName=scene_name, sourceName=created))
                    print('Added AutoScreen to scene', scene_name)
                except Exception as e:
                    try:
                        c.call(requests.CreateSceneItem(sceneName=scene_name, sourceName=created))
                        print('CreateSceneItem used to add', created)
                    except Exception as e2:
                        print('Failed to add AutoScreen to scene', e, e2)
    # Ensure Desktop Audio present: inputs already show 'Desktop Audio'
    print('\nFinal inputs:')
    for i in c.call(requests.GetInputList()).getInputs():
        print(i)
    # start recording
    print('\nStarting recording')
    c.call(requests.StartRecord())
    print('Started; checking recording status...')
    print(c.call(requests.GetRecordStatus()).datain)
    c.disconnect()
except Exception as e:
    print('connect failed', e)
    sys.exit(1)
